export const getGetPurchaseRequestStatsUrl = (params?: GetPurchaseRequestStatsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/purchase-requests/stats?${stringifiedParams}` : `/api/purchase-requests/stats`
}

